{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.FLIPKART_SOR_FACT_ITEM as WITH fsn_map AS ( SELECT DISTINCT TRIM(FSN) AS fsn, MAX(TRIM(SKU)) AS sku FROM snitch_db.maplemonk.gs_FSN_SKU_MAPPING_sheet1 WHERE FSN IS NOT NULL GROUP BY 1 ), historical_data AS ( SELECT h.fsn AS marketplace_sku_code, COALESCE(m.sku, h.fsn) AS sku, TRY_TO_DATE(TO_VARCHAR(h.order_date), \'YYYYMMDD\') AS order_date, TRY_CAST(TO_VARCHAR(h.units) AS INT) AS quantity_sold, DIV0(TRY_CAST(TO_VARCHAR(h.mrp_sales) AS FLOAT), TRY_CAST(TO_VARCHAR(h.units) AS INT)) AS unit_mrp, TRY_CAST(TO_VARCHAR(h.SP) AS FLOAT) AS unit_sp, (TRY_CAST(TO_VARCHAR(h.rvp_units) AS INT) + TRY_CAST(TO_VARCHAR(h.rto_units) AS INT)) AS return_quantity, h.return_reason, \'Historical\' AS source_type, NULL AS seller_order_id, NULL AS pincode FROM SNITCH_DB.MAPLEMONK.FK_SOR_DATA_AUG_TO_OCT h LEFT JOIN fsn_map m ON h.fsn = m.fsn ) , current_sales_raw AS ( SELECT s.fsn, NULL AS order_id, TRY_TO_DATE(TO_VARCHAR(s.order_date), \'YYYYMMDD\') AS order_date, TRY_CAST(TO_VARCHAR(s.units) AS INT) AS quantity, TRY_CAST(TO_VARCHAR(s.mrp_sales) AS FLOAT) AS total_mrp_sales, TRY_CAST(TO_VARCHAR(s.rvp_units) AS INT) AS rvp_units, TRY_CAST(TO_VARCHAR(s.rto_units) AS INT) AS rto_units, s.return_reason, NULL AS pincode FROM snitch_db.maplemonk.S3_FK_SOR_SALES_RETURNS s WHERE TRY_TO_DATE(TO_VARCHAR(s.order_date), \'YYYYMMDD\') >= \'2023-11-01\' ) , discount_logic AS ( SELECT TRIM(FSN) AS fsn, TRIM(SKU) AS sku, TRY_CAST(MRP AS FLOAT) AS mrp, TRY_CAST(REPLACE(PARSE_JSON(\"_AB_ADDITIONAL_PROPERTIES\"):\"Disc %\"::STRING, \'%\', \'\') AS FLOAT) AS disc_percent, TRY_TO_DATE(\"Start Date \", \'DD/MM/YY\') AS start_date, TRY_TO_DATE(\"End Date \", \'DD/MM/YY\') AS end_date FROM snitch_db.maplemonk.S3_FK_SOR_DISCOUNT ), current_data_processed AS ( SELECT s.fsn AS marketplace_sku_code, COALESCE(m.sku, d.sku, s.fsn) AS sku, s.order_date, s.quantity AS quantity_sold, COALESCE(d.mrp, DIV0(s.total_mrp_sales, s.quantity)) AS unit_mrp, CASE WHEN d.fsn IS NOT NULL THEN d.mrp * (1 - (d.disc_percent / 100)) ELSE COALESCE(d.mrp, DIV0(s.total_mrp_sales, s.quantity)) END AS unit_sp, (COALESCE(s.rvp_units, 0) + COALESCE(s.rto_units, 0)) AS return_quantity, s.return_reason, \'Current\' AS source_type, s.order_id AS seller_order_id, s.pincode FROM current_sales_raw s LEFT JOIN fsn_map m ON s.fsn = m.fsn LEFT JOIN discount_logic d ON s.fsn = d.fsn AND s.order_date BETWEEN d.start_date AND d.end_date ), combined_data AS ( SELECT sku, marketplace_sku_code, order_date, seller_order_id, pincode, quantity_sold, return_quantity, return_reason, unit_mrp AS mrp, CASE WHEN unit_sp > unit_mrp THEN unit_mrp ELSE unit_sp END AS sp FROM historical_data UNION ALL SELECT sku, marketplace_sku_code, order_date, seller_order_id, pincode, quantity_sold, return_quantity, return_reason, unit_mrp AS mrp, CASE WHEN unit_sp > unit_mrp THEN unit_mrp ELSE unit_sp END AS sp FROM current_data_processed ), category_from_inv AS ( SELECT sku_group, category FROM snitch_db.maplemonk.Flipkart_SOR_INV_report QUALIFY ROW_NUMBER() OVER(PARTITION BY sku_group ORDER BY date DESC) = 1 ), prod_details AS ( SELECT * FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) = 1 ) SELECT c.sku, REGEXP_REPLACE(c.sku, \'-[^-]*$\', \'\') AS sku_group, CASE WHEN c.sku LIKE \'%-%\' THEN SPLIT_PART(c.sku, \'-\', ARRAY_SIZE(SPLIT(c.sku, \'-\'))) ELSE NULL END AS size, c.sp, c.mrp, (c.mrp - c.sp) AS discount, c.seller_order_id, c.order_date, c.quantity_sold AS total_quantity, c.pincode, c.return_quantity, c.return_reason, CASE WHEN LOWER(c.return_reason) LIKE \'%size%\' THEN \'Size & Fit Issue\' WHEN LOWER(c.return_reason) LIKE \'%quality%\' THEN \'Quality Issue\' ELSE \'Other\' END AS categorized_return_reason, p.product_name, cat.category, p.title, p.color FROM combined_data c LEFT JOIN prod_details p ON REGEXP_REPLACE(c.sku, \'-[^-]*$\', \'\') = p.sku_group LEFT JOIN category_from_inv cat ON REGEXP_REPLACE(c.sku, \'-[^-]*$\', \'\') = cat.sku_group;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            